 const [settingsOpen,setSettingsOpen]=useState(false),[clientId,setClientId]=useState(''),[apiKey,setApiKey]=useState(''),[aiModel,setAiModel]=useState(guest?RECOMMENDED_OPENROUTER_MODEL:'gpt-4.1-mini'),[aiProvider,setAiProvider]=useState<AiProvider>(guest?'openrouter':'openai');
