 const organize=async(input=text,reader=mode)=>{if(!input.trim())return;setExtractError('');setExtractErrorCode('');setBusy('extract');try{const r=guest&&reader==='ai'?await apiRequest('/api/guest-extract',post(apiKey.trim()?{text:input,provider:aiProvider,key:apiKey,model:aiModel}:{text:input})):await request('/api/extract',post({text:input,mode:reader}));review(r.people,r.notice)}catch(e){setExtractErrorCode(e instanceof TypeError?'ai_connection':String((e as any)?.code||''));setExtractError(errorMessage(e));toast.error(errorMessage(e))}finally{setBusy('')}};
 useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const controller=new AbortController();const tool={name:'stage_people_note',title:'Review a people note',description:'Extract details from a note and open the editable review. Does not save any profiles.',inputSchema:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:60000}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async(input:any)=>{if(typeof input?.text!=='string'||!input.text.trim()||input.text.length>60000)throw new Error('A note of 1 to 60,000 characters is required.');setText(input.text);setView('Inbox');const r=await request('/api/extract',post({text:input.text,mode:'built-in'}));review(r.people,r.notice);return{status:'staged_for_review',profiles:r.people.length,saved:false}}};try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}return()=>controller.abort()},[]);
 const saveDrafts=async()=>{if(drafts.some(p=>!p.name.trim())){toast.error('Give every profile a name before saving.');return}setBusy('save');try{const submitted=drafts.map(p=>{const old=p.mergeId?people.find(x=>x.id===p.mergeId):undefined;if(p.mergeId&&!old)throw new Error('The person selected for this update is no longer available. Refresh and choose how to save this draft.');const f=Object.fromEntries(Object.entries(p.fields).filter(([,v])=>v.trim()).map(([k,v])=>[k,v.trim()]));return old?{...p,id:old.id,version:old.version,fields:{...old.fields,...f},notes:old.notes===p.notes?old.notes:[old.notes,p.notes].filter(Boolean).join('\n\n')}:{...p,fields:f}});if(new Set(submitted.map(p=>p.id)).size!==submitted.length)throw new Error('Two drafts update the same person. Save those updates separately.');const r=await request('/api/people',post({people:submitted}));await refresh();if(r.conflicts.length){setDrafts(drafts.filter((_,i)=>r.conflicts.includes(submitted[i].id)));toast.error(`${r.saved.length} saved. ${r.conflicts.length} changed elsewhere; review the latest profiles and retry.`)}else{setReviewOpen(false);setDrafts([]);setText('');toast.success(`${r.saved.length} profile${r.saved.length===1?'':'s'} saved. Your folders and charts are updated.`)}}catch(e){toast.error(errorMessage(e))}finally{setBusy('')}};
