 const importGoogleSheet=async()=>{const match=sheetUrl.match(/^https:\/\/docs\.google\.com\/spreadsheets\/d\/([\w-]+)/);if(!match){toast.error('Paste a Google Sheets document URL.');return}if(!config.googleClientId){setSettingsOpen(true);toast.info('Set up Google connection first, or download the sheet as XLSX/CSV and import the file.');return}if(!googleReady){loadGoogle().then(()=>setGoogleReady(true)).catch(e=>toast.error(errorMessage(e)));toast.info('Google sign-in is loading. Try again in a moment.');return}setBusy('sheets');try{const token=await authorizeGoogle(config.googleClientId,'https://www.googleapis.com/auth/spreadsheets.readonly');const r=await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${match[1]}?fields=sheets(properties(title))`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw new Error('Google could not read this sheet. Check your account, permissions, and that the Sheets API is enabled.');const d:any=await r.json();const ranges=d.sheets.map((s:any)=>`ranges=${encodeURIComponent("'"+s.properties.title.replaceAll("'","''")+"'")}`).join('&');const values=await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${match[1]}/values:batchGet?${ranges}`,{headers:{Authorization:`Bearer ${token}`}});if(!values.ok)throw new Error('The spreadsheet values could not load.');const v:any=await values.json();const sheets=v.valueRanges.map((r:any,i:number)=>{return{name:d.sheets[i].properties.title,rows:rowsFromGrid(r.values||[])}}).filter((s:any)=>s.rows.length);if(!sheets.length)throw new Error('The spreadsheet has no rows.');setImportData({sheets});setImportFile(null);setSheetIndex('0');setNameColumn(Object.keys(sheets[0].rows[0]).find(k=>/^(full ?)?name$/i.test(k))||Object.keys(sheets[0].rows[0])[0]);setImportOpen(true)}catch(e){toast.error(errorMessage(e))}finally{setBusy('')}};
